std::vector<uint8_t> largeFixture(size_t count,bool repeat){auto b=fixture();auto original=b;auto xdata=(0x600+count*12+511)&~size_t(511);b.resize(xdata+512);std::fill(b.begin()+0x600,b.end(),0);size_t opt=0x98,sec=opt+240;put<uint32_t>(b,opt+116+24,static_cast<uint32_t>(count*12));put<uint32_t>(b,sec+40+8,static_cast<uint32_t>(count*12));put<uint32_t>(b,sec+40+16,static_cast<uint32_t>(count*12));put<uint32_t>(b,sec+80+12,0x1000000);put<uint32_t>(b,sec+80+20,static_cast<uint32_t>(xdata));put<uint32_t>(b,opt+56,0x1001000);std::copy(original.begin()+0x800,original.begin()+0x808,b.begin()+xdata);for(size_t i=0;i<(repeat?count:size_t(1));++i){put<uint32_t>(b,0x600+i*12,0x1000);put<uint32_t>(b,0x604+i*12,0x1020);put<uint32_t>(b,0x608+i*12,0x1000000);}return b;}
